-- RootishArrayStack：块级增长与收缩。
INSERT INTO knowledge_point (name, description, course_id, parent_id, content_key, content_source, content_version, content_review_status, sort_order, deleted)
SELECT 'RootishArrayStack 的块增长与收缩', '容量不足时追加长度 r+1 的块；删除后若倒数第二块已足以容纳元素，则持续删除尾块。', course.id, parent.id, 'ods-rootisharraystack-grow-shrink', 'AISTU', 1, 'REVIEWED', 32, 0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='ods-rootisharraystack-grow-shrink' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id, content_key, content_version, review_status, title, lesson_json, check_json)
SELECT point.id,'ods-rootisharraystack-grow-shrink',1,'REVIEWED','RootishArrayStack 的块增长与收缩',JSON_OBJECT('summary','若 r 个块总容量 r(r+1)/2 小于 n+1，grow 追加长度 r+1 的块。删除后，只要移除倒数第二块仍可容纳 n 个元素，shrink 就删除尾块。两者不复制既有元素。','steps',JSON_ARRAY('容量不足时只在末尾增加一个更长的新块','grow 不搬移已有元素','删除后检查末尾是否存在多余空块','shrink 只删除尾块，保持最多两个块未满'),'prerequisite',JSON_OBJECT('contentKey','ods-rootisharraystack-update','title','RootishArrayStack 的按位插入与删除','description','先理解更新完成后才评估块数量。'),'nextStep',JSON_OBJECT('contentKey','ods-rootisharraystack-space','title','RootishArrayStack 的浪费空间界','description','继续理解块收缩为何限制额外空间。')),JSON_OBJECT('id','rootisharraystack-grow-shrink-v1','prompt','RootishArrayStack 的 grow 与 ArrayStack 的 resize 的关键差异是什么？','options',JSON_ARRAY(JSON_OBJECT('id','NO_COPY','text','grow 只追加新块，不复制已有元素'),JSON_OBJECT('id','COPY_ALL','text','grow 必须把所有元素复制到一个更大数组')),'correctOptionId','NO_COPY','correctExplanation','正确：RootishArrayStack 保留旧块，只增加一个新数组块。','incorrectExplanation','不正确：整体复制是单后备数组 resize 的特征，不是块级 grow。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='ods-rootisharraystack-grow-shrink' AND existing.content_version=1 WHERE point.content_key='ods-rootisharraystack-grow-shrink' AND existing.id IS NULL;
